; shapes.asm -- chapter 39: the shape of a collision
; generated by gen39.py
        INCLUDE "msx.inc"
        OUTPUT "shapes.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; Ball B at every place from 18 pixels left of ball A to 18 right, and
; from 18 above to 18 below, two frames each: C read for each place, and
; boxed and touched asked; then the map drawn.
stat    EQU VARS                ; the status the interrupt routine read
ticks   EQU VARS + 1            ; frames, two bytes
names   EQU $C400               ; the copy of the 768 names
copy    EQU $C800               ; the copy of the sprites' attributes
ATT_TABLE EQU $1B00
PAT_TABLE EQU $3800
END_MARK EQU $D0                ; a Y of 208 ends the table
dx      EQU VARS + 3            ; ball B's place, off ball A
dy      EQU VARS + 4
mapc    EQU VARS + 5            ; the place's byte in map_c, two bytes
map_c   EQU $D000               ; each place: C after it, $20 or 0
map_t   EQU $D600               ; 0 boxes apart, 1 boxes meet, 2 pixels meet
bitmap  EQU $DC00               ; the map drawn, 14 bytes x 112 lines
blk_src EQU VARS + $10          ; showblk's working bytes, in the RAM
blk_rc  EQU VARS + $12
blk_k   EQU VARS + $14
blk_w   EQU VARS + $15
blk_h   EQU VARS + $16
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $9F          ; colours  $2000, one set for three thirds
        VDP_REG 4, $00          ; shapes   $0000, one set for three thirds
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $1B00        ; no sprites
        ld a, END_MARK
        out (VDP_DATA), a
        VRAM_WRITE $0000        ; the shapes: all paper ...
        ld bc, 2048
.shp:   xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .shp
        VRAM_WRITE $0008        ; ... but name 1, the brick
        ld hl, brick
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE $2000        ; the colours: black on white ...
        ld bc, 2048
.col:   ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .col
        VRAM_WRITE $2008        ; ... but the brick's
        ld hl, brick + 8
        ld bc, (8 << 8) | VDP_DATA
        otir
        VRAM_WRITE PAT_TABLE    ; the sprite patterns
        ld hl, patterns
        ld bc, (96 << 8) | VDP_DATA
        otir
        ld hl, blank            ; the names, into their copy ...
        ld de, names
        ld bc, 768
        ldir
        VRAM_WRITE $1800        ; ... and from there to the VDP
        ld hl, names
        ld bc, 768
.nam:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .nam
        ld hl, 0
        ld (ticks), hl
        ld a, END_MARK          ; no sprites in the copy yet
        ld (copy), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld hl, start            ; ball A, and ball B
        ld de, copy
        ld bc, 9
        ldir
        in a, (VDP_CTRL)        ; F cleared: the first interrupt ends a frame
        VDP_REG 1, $E2          ; display on, interrupt on, sprites 16 x 16
        ei
        ld hl, map_c
        ld (mapc), hl
        ld a, -18
        ld (dy), a
.dy:    ld a, -18
        ld (dx), a
.dx:    ld a, (dy)              ; ball B at A's place + (dx, dy)
        add a, 87
        ld (copy + 4), a
        ld a, (dx)
        add a, 100
        ld (copy + 5), a
        halt                    ; the first interrupt sends it,
        halt                    ; the second reads the status of a picture of it
        ld a, (stat)
        and $20                 ; C
        ld hl, (mapc)
        ld (hl), a
        ld a, (copy + 1)
        ld b, a
        ld a, (copy)
        ld c, a                 ; B, C: ball A
        ld a, (copy + 5)
        ld d, a
        ld a, (copy + 4)
        ld e, a                 ; D, E: ball B
        call boxed
        ld a, 0
        jr nc, .keep            ; 0: the boxes are apart
        call touched
        ld a, 1
        jr z, .keep             ; 1: the boxes meet, the pixels do not
        inc a                   ; 2: the pixels meet
.keep:  ld hl, (mapc)
        ld de, map_t - map_c
        add hl, de
        ld (hl), a
        ld hl, (mapc)
        inc hl
        ld (mapc), hl
        ld a, (dx)
        inc a
        ld (dx), a
        cp 19
        jr nz, .dx
        ld a, (dy)
        inc a
        ld (dy), a
        cp 19
        jr nz, .dy
        di                      ; the sweep is over
        VDP_REG 1, $82          ; display off
        VRAM_WRITE ATT_TABLE    ; no sprites
        ld a, END_MARK
        out (VDP_DATA), a
        call draw               ; the map, in the RAM
        ld hl, bitmap
        ld de, (14 << 8) | 14
        ld bc, (5 << 8) | 9
        ld a, 16
        call showblk            ; and as characters
        VDP_REG 1, $C2          ; display on
done:   jr done

; isr: every frame. The status kept in stat, the copy of the sprites'
; attributes sent (the paper is over: at full speed, chapter 20), the frame
; counted. Keeps AF, BC, HL
isr:    push af
        push bc
        push hl
        in a, (VDP_CTRL)        ; the status: F, 5S and C; the signal down
        ld (stat), a
        VRAM_WRITE ATT_TABLE
        ld hl, copy
        ld bc, (9 << 8) | VDP_DATA
        otir
        ld hl, (ticks)
        inc hl
        ld (ticks), hl
        pop hl
        pop bc
        pop af
        ei
        ret

; boxed: B, C = X, Y of one ball and D, E of the other -> carry if their
; boxes of 16 x 16 share a pixel: X and Y both less than 16 apart. Uses A
boxed:  ld a, d                 ;  5
        sub b                   ;  5  the difference of the X
        add a, 15               ;  8  -15 to 15 become 0 to 30
        cp 31                   ;  8
        ret nc                  ; 12, or 6  16 or more apart
        ld a, e                 ;  5
        sub c                   ;  5  the difference of the Y
        add a, 15               ;  8
        cp 31                   ;  8
        ret                     ; 11  carry: the boxes meet

; touched: B, C = X, Y of one ball and D, E of the other, whose boxes meet ->
; NZ if a pixel of one is a pixel of the other. The ball's rows are in
; shifted, four bytes each, moved 0 to 7 pixels right: copy s at 64 x s.
; Uses A, BC, DE, HL
touched: ld a, d                ;  5
        sub b                   ;  5  dx: the second ball's X less the first's
        jr nc, .order           ; 13, or 8
        push bc                 ; 12  the second ball is on the left:
        push de                 ; 12  the two change places
        pop bc                  ; 11
        pop de                  ; 11
        neg                     ; 10
.order: ld l, a                 ;  5  L: dx, 0 to 15. (B, C) is the left ball
        ld a, e                 ;  5
        sub c                   ;  5  dy: the right ball's Y less the left's
        ld e, 0                 ;  8  the right ball lower: its row 0 ...
        jr nc, .lower           ; 13, or 8
        neg                     ; 10  higher: its row -dy ...
        ld e, a                 ;  5
        xor a                   ;  5  ... meets the left ball's row 0
.lower: ld c, a                 ;  5  C: the left ball's first row
        add a, e                ;  5
        sub 16                  ;  8
        neg                     ; 10
        ld b, a                 ;  5  B: the rows both cover, 16 - |dy|
        ld a, l                 ;  5
        and 3                   ;  8
        rrca                    ;  5
        rrca                    ;  5  (dx AND 3) x 64
        sla e                   ; 10
        sla e                   ; 10  + 4 x the right ball's first row
        add a, e                ;  5
        ld e, a                 ;  5
        ld d, high shifted      ;  8  DE: that row of copy dx AND 7
        bit 2, l                ; 10
        jr z, .page             ; 13, or 8
        inc d                   ;  5  copies 4 to 7 are in the next page
.page:  bit 3, l                ; 10
        jr z, .near             ; 13, or 8
        dec de                  ;  7  dx of 8 or more: a byte to the left
.near:  ld a, c                 ;  5
        add a, a                ;  5
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high shifted      ;  8  HL: the left ball's first row, copy 0
.row:   ld a, (de)              ;  8
        and (hl)                ;  8  the first byte of the two
        ret nz                  ; 12, or 6  a pixel of both: they touch
        inc de                  ;  7
        inc l                   ;  5
        ld a, (de)              ;  8
        and (hl)                ;  8  the second
        ret nz                  ; 12, or 6
        inc de                  ;  7
        inc de                  ;  7
        inc de                  ;  7
        inc l                   ;  5
        inc l                   ;  5
        inc l                   ;  5  the next row of each
        djnz .row               ; 14, or 9
        xor a                   ;  5
        ret                     ; 11  Z: no pixel in common

; draw: the map in bitmap, a block of 3 x 3 pixels a place: all ink where C
; came, a chequer where only the boxes meet, paper where they are apart
draw:   ld hl, bitmap           ; all paper
        ld de, bitmap + 1
        ld bc, 1567
        ld (hl), 0
        ldir
        ld hl, map_c
        ld c, 0                 ; C: the place's top line in the map
.row:   ld b, 0                 ; B: its left column
.place: ld a, (hl)
        or a
        ld e, %111              ; C came: three pixels on each line
        ld d, %111
        jr nz, .put
        push hl
        ld de, map_t - map_c
        add hl, de
        ld a, (hl)
        pop hl
        or a
        jr z, .skip             ; the boxes apart: paper
        ld e, %101              ; the boxes meet: a chequer
        ld d, %010
.put:   call block
.skip:  inc hl
        ld a, b
        add a, 3
        ld b, a
        cp 111
        jr nz, .place
        ld a, c
        add a, 3
        ld c, a
        cp 111
        jr nz, .row
        ret

; block: the place at (B, C) of the bitmap, three lines of three pixels: the
; bits of E on the first and the third, of D on the second. Keeps BC, DE, HL
block:  push hl
        push de
        ld a, e
        call three
        inc c
        pop de
        push de
        ld a, d
        call three
        inc c
        pop de
        push de
        ld a, e
        call three
        dec c
        dec c
        pop de
        pop hl
        ret

; three: A's three low bits as pixels (B, C), (B + 1, C), (B + 2, C). Keeps
; BC. Uses A, DE, HL
three:  push bc
        ld e, a
        ld d, 3
.bit:   srl e                   ; the next bit
        jr nc, .no
        push de
        call plot
        pop de
.no:    inc b
        dec d
        jr nz, .bit
        pop bc
        ret

; plot: the pixel (B, C) of the bitmap set, B across and C down. Uses A,
; DE, HL
plot:   ld l, c
        ld h, 0
        add hl, hl              ; the line x 2
        ld e, l
        ld d, h
        add hl, hl
        add hl, hl
        add hl, hl              ; x 16
        or a
        sbc hl, de              ; x 14: the bytes of a line
        ld a, b
        rrca
        rrca
        rrca
        and $1F
        ld e, a
        ld d, 0
        add hl, de              ; + the byte across
        ld de, bitmap
        add hl, de
        ld a, b
        and 7
        ld e, a
        ld a, $80
        jr z, .set
.shift: rrca                    ; the pixel's bit
        dec e
        jr nz, .shift
.set:   or (hl)
        ld (hl), a
        ret

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; showblk: a bitmap in the RAM or the ROM, W bytes across and 8 x H lines
;          down, line after line, sent to the VDP as W x H character shapes
;          from code A, and those characters put on the screen in a block
;          whose top left is row B, column C. HL = the bitmap, D = W, E = H.
;          The display must be off (chapter 20).
showblk: ld (blk_src), hl
        ld (blk_rc), bc
        ld (blk_k), a
        ld a, d
        ld (blk_w), a
        ld a, e
        ld (blk_h), a
        ld a, (blk_k)
        ld l, a
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl              ; the shape of character K is at K x 8
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, (blk_w)
        ld e, a
        ld d, 0                 ; DE: W, from one line to the next
        ld hl, (blk_src)
        ld a, (blk_h)
        ld b, a                 ; B: the rows of cells left
sb1:    push bc
        push hl                 ; HL: the top line of this row of cells
        ld a, (blk_w)
        ld c, a                 ; C: the cells left in the row
sb2:    push hl
        ld b, 8
sb3:    ld a, (hl)              ; the cell's eight lines, a byte each
        out (VDP_DATA), a
        add hl, de              ; one line down
        djnz sb3
        pop hl
        inc hl                  ; the next cell: one byte across
        dec c
        jr nz, sb2
        pop hl
        ld b, 8
sb4:    add hl, de
        djnz sb4                ; eight lines down: the next row of cells
        pop bc
        djnz sb1
        ld bc, (blk_rc)
        ld a, (blk_k)
        ld d, a                 ; D: the next code
        ld a, (blk_h)
        ld e, a                 ; E: the rows left
sn1:    call at                 ; the name of (B, C)
        ld a, (blk_w)
        ld h, a
sn2:    ld a, d
        out (VDP_DATA), a
        inc d
        dec h
        jr nz, sn2
        inc b
        dec e
        jr nz, sn1
        ret
boxes:  ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
brick:  db $FF, $80, $80, $80, $FF, $08, $08, $08
        db $14, $14, $14, $14, $14, $14, $14, $14
patterns:                       ; ball 0, face 4, inside of the face 8
        db $00, $07, $0F, $1F, $3F, $7F, $7F, $7F
        db $7F, $7F, $7F, $3F, $1F, $0F, $07, $00
        db $00, $E0, $F0, $F8, $FC, $FE, $FE, $FE
        db $FE, $FE, $FE, $FC, $F8, $F0, $E0, $00
        db $07, $18, $20, $40, $46, $86, $80, $80
        db $80, $88, $47, $40, $20, $18, $07, $00
        db $E0, $18, $04, $02, $62, $61, $01, $01
        db $01, $11, $E2, $02, $04, $18, $E0, $00
        db $00, $07, $1F, $3F, $39, $79, $7F, $7F
        db $7F, $77, $38, $3F, $1F, $07, $00, $00
        db $00, $E0, $F8, $FC, $9C, $9E, $FE, $FE
        db $FE, $EE, $1C, $FC, $F8, $E0, $00, $00
start:  db $57, $64, $00, $01, $57, $64, $00, $04, $D0   ; ball A, ball B
        db 0                    ; the byte before the table: touched may read it
        ALIGN 512, 0
shifted:                        ; the ball moved 0-7 pixels, 4 bytes a row
        db $00, $00, $00, $00, $07, $E0, $00, $00
        db $0F, $F0, $00, $00, $1F, $F8, $00, $00
        db $3F, $FC, $00, $00, $7F, $FE, $00, $00
        db $7F, $FE, $00, $00, $7F, $FE, $00, $00
        db $7F, $FE, $00, $00, $7F, $FE, $00, $00
        db $7F, $FE, $00, $00, $3F, $FC, $00, $00
        db $1F, $F8, $00, $00, $0F, $F0, $00, $00
        db $07, $E0, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $03, $F0, $00, $00
        db $07, $F8, $00, $00, $0F, $FC, $00, $00
        db $1F, $FE, $00, $00, $3F, $FF, $00, $00
        db $3F, $FF, $00, $00, $3F, $FF, $00, $00
        db $3F, $FF, $00, $00, $3F, $FF, $00, $00
        db $3F, $FF, $00, $00, $1F, $FE, $00, $00
        db $0F, $FC, $00, $00, $07, $F8, $00, $00
        db $03, $F0, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $01, $F8, $00, $00
        db $03, $FC, $00, $00, $07, $FE, $00, $00
        db $0F, $FF, $00, $00, $1F, $FF, $80, $00
        db $1F, $FF, $80, $00, $1F, $FF, $80, $00
        db $1F, $FF, $80, $00, $1F, $FF, $80, $00
        db $1F, $FF, $80, $00, $0F, $FF, $00, $00
        db $07, $FE, $00, $00, $03, $FC, $00, $00
        db $01, $F8, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $FC, $00, $00
        db $01, $FE, $00, $00, $03, $FF, $00, $00
        db $07, $FF, $80, $00, $0F, $FF, $C0, $00
        db $0F, $FF, $C0, $00, $0F, $FF, $C0, $00
        db $0F, $FF, $C0, $00, $0F, $FF, $C0, $00
        db $0F, $FF, $C0, $00, $07, $FF, $80, $00
        db $03, $FF, $00, $00, $01, $FE, $00, $00
        db $00, $FC, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $7E, $00, $00
        db $00, $FF, $00, $00, $01, $FF, $80, $00
        db $03, $FF, $C0, $00, $07, $FF, $E0, $00
        db $07, $FF, $E0, $00, $07, $FF, $E0, $00
        db $07, $FF, $E0, $00, $07, $FF, $E0, $00
        db $07, $FF, $E0, $00, $03, $FF, $C0, $00
        db $01, $FF, $80, $00, $00, $FF, $00, $00
        db $00, $7E, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $3F, $00, $00
        db $00, $7F, $80, $00, $00, $FF, $C0, $00
        db $01, $FF, $E0, $00, $03, $FF, $F0, $00
        db $03, $FF, $F0, $00, $03, $FF, $F0, $00
        db $03, $FF, $F0, $00, $03, $FF, $F0, $00
        db $03, $FF, $F0, $00, $01, $FF, $E0, $00
        db $00, $FF, $C0, $00, $00, $7F, $80, $00
        db $00, $3F, $00, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $1F, $80, $00
        db $00, $3F, $C0, $00, $00, $7F, $E0, $00
        db $00, $FF, $F0, $00, $01, $FF, $F8, $00
        db $01, $FF, $F8, $00, $01, $FF, $F8, $00
        db $01, $FF, $F8, $00, $01, $FF, $F8, $00
        db $01, $FF, $F8, $00, $00, $FF, $F0, $00
        db $00, $7F, $E0, $00, $00, $3F, $C0, $00
        db $00, $1F, $80, $00, $00, $00, $00, $00
        db $00, $00, $00, $00, $00, $0F, $C0, $00
        db $00, $1F, $E0, $00, $00, $3F, $F0, $00
        db $00, $7F, $F8, $00, $00, $FF, $FC, $00
        db $00, $FF, $FC, $00, $00, $FF, $FC, $00
        db $00, $FF, $FC, $00, $00, $FF, $FC, $00
        db $00, $FF, $FC, $00, $00, $7F, $F8, $00
        db $00, $3F, $F0, $00, $00, $1F, $E0, $00
        db $00, $0F, $C0, $00, $00, $00, $00, $00
blank:  ds 768, 0               ; no tiles: every name 0, the paper
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
